// --- Robust text extraction: handles multiple possible upstream shapes:
// 1) OpenAI Chat Completions style: message.content / choices[0].message.content
// 2) OpenAI Responses API style: output[0].content[0].text (with type 'output_text')
// 3) Gemini style: content.parts[0].text
function extractText(json) {
  if (Array.isArray(json.output)) {
    for (const item of json.output) {
      if (item.type === 'message' && Array.isArray(item.content)) {
        const textBlock = item.content.find(c => c.type === 'output_text' || typeof c.text === 'string');
        if (textBlock?.text) return textBlock.text;
      }
    }
  }
  return (
    json.message?.content ??
    json.content ??
    json.choices?.[0]?.message?.content ??
    json.content?.parts?.[0]?.text ??
    json.output_text ??
    ''
  );
}

const raw = extractText($input.item.json);
if (!raw) {
  throw new Error('No text content found in AI response. Full input: ' + JSON.stringify($input.item.json).slice(0, 500));
}

let cleaned = raw.replace(/```json|```/g, '').trim();
const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
if (jsonMatch) cleaned = jsonMatch[0];

// Normalize smart quotes some models emit
cleaned = cleaned
  .replace(/[\u201C\u201D]/g, '"')
  .replace(/[\u2018\u2019]/g, "'");

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Failed to parse Gemini output as JSON: ' + e.message + ' | RAW (first 800 chars): ' + cleaned.slice(0, 800));
}

if (!parsed.body || !parsed.subject || !parsed.proposed_slots_iso) {
  throw new Error('Parsed JSON missing required fields: ' + JSON.stringify(parsed).slice(0, 500));
}

const rawFrom = $('Gmail Trigger').item.json.From;
const emailMatch = rawFrom.match(/<(.+?)>/);
const leadEmail = emailMatch ? emailMatch[1].trim() : rawFrom.trim();

const baseUrl = 'https://n8n-smady-adgtdkg5hvacf7fs.canadacentral-01.azurewebsites.net/webhook/book-slot';
const slots = parsed.proposed_slots_iso;
const slotLabels = parsed.body.match(/<li>(.*?)<\/li>/gs) || [];

function parseSlotLabel(raw) {
  return raw.replace(/<\/?li>/g, '').replace(/<strong>|<\/strong>/g, '').replace(/<br\s*\/?>/g, '').trim();
}

function getDayMonth(iso) {
  const d = new Date(iso);
  const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const months = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
  return {
    weekday: days[d.getDay()],
    day: d.getDate(),
    month: months[d.getMonth()]
  };
}

let slotCards = '';
slots.forEach((iso, i) => {
  const label = slotLabels[i] ? parseSlotLabel(slotLabels[i]) : `Slot ${i+1}`;
  const url = `${baseUrl}?slot=${i+1}&email=${encodeURIComponent(leadEmail)}&time=${encodeURIComponent(iso)}`;
  const dt = getDayMonth(iso);

  slotCards += `
  <tr>
    <td style="padding:5px 0;">
      <table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;background:#ffffff;">
        <tr>
          <td width="70" style="background:#EFF6FF;padding:0;text-align:center;vertical-align:middle;">
            <div style="padding:16px 12px;">
              <div style="font-size:10px;font-weight:700;color:#3B82F6;letter-spacing:0.08em;margin-bottom:4px;">${dt.month}</div>
              <div style="font-size:26px;font-weight:700;color:#1E40AF;line-height:1;">${dt.day}</div>
            </div>
          </td>
          <td style="padding:14px 16px;vertical-align:middle;">
            <div style="font-size:14px;font-weight:700;color:#111827;margin-bottom:3px;">${dt.weekday}</div>
            <div style="font-size:12px;color:#6b7280;line-height:1.5;">${label}</div>
          </td>
          <td width="110" style="padding:14px 16px;text-align:center;vertical-align:middle;">
            <a href="${url}" style="display:inline-block;background:#1D4ED8;color:#ffffff;padding:9px 16px;border-radius:8px;text-decoration:none;font-size:13px;font-weight:600;white-space:nowrap;line-height:1;">Book slot</a>
          </td>
        </tr>
      </table>
    </td>
  </tr>`;
});

const newBody = `
<div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;background:#f3f4f6;padding:20px;">
  <div style="background:#ffffff;border-radius:16px;overflow:hidden;border:1px solid #e5e7eb;">
