      </div>
    </div>
  </div>
  <p style="text-align:center;font-size:11px;color:#9ca3af;margin-top:16px;">Claude Smadlytics · AI Sales Automation</p>
</div>`;

return [{
  json: {
    subject: parsed.subject.replace(/^=+/, '').trim(),
    body: styledBody,
    lead_email: leadEmail
  }
}];

const snippet = $json.snippet || "";

const reply = snippet
  .split(/\n?\s*On .*? wrote:/i)[0]   // Split at "On ... wrote:"
  .trim();

return {
  ...$json,
  latestReply: reply
};

const clientName = $json['Client Name'];
const clientEmail = $json['Client Email'];
const meetingDate = $json['Meeting Date']; // e.g. '2026-08-05'
const meetingTime = ($json['Meeting Time (24hr, IST)'] || '').trim(); // e.g. '14:30'
const durationMinutes = Number($json['Duration (minutes)']) || 30;
const title = $json['Meeting Title'] || 'Discovery Call';
const notes = $json['Notes / Description'] || `Meeting scheduled manually with ${clientName}`;

if (!clientEmail || !meetingDate || !meetingTime) {
  throw new Error('Missing required fields. Got: ' + JSON.stringify($json));
}

const timeMatch = meetingTime.match(/^(\d{1,2}):(\d{2})$/);
if (!timeMatch) {
  throw new Error('Meeting Time must be in HH:mm 24-hour format, got: ' + meetingTime);
}

// Asia/Kolkata is a fixed UTC+5:30 offset, so we can build the ISO string directly
const hh = timeMatch[1].padStart(2, '0');
const mm = timeMatch[2];
const isoWithOffset = `${meetingDate}T${hh}:${mm}:00+05:30`;
const startDt = new Date(isoWithOffset);

if (isNaN(startDt.getTime())) {
  throw new Error('Could not parse meeting date/time: ' + isoWithOffset);
}

const endDt = new Date(startDt.getTime() + durationMinutes * 60000);

return [{
  json: {
    lead_email: clientEmail,
    client_name: clientName,
    slot_number: 'manual',
    start_time: startDt.toISOString(),
    end_time: endDt.toISOString(),
    summary: title,
    description: notes
  }
}];

const query = $json.query || {};

// Map incoming webhook keys to your variables (supporting both formats)
const rawEmail = query.email || query['Client Email'];
const meetingDate = query['Meeting Date'];
const meetingTime = query['Meeting Time'];

// Combine Meeting Date and Meeting Time if 'time' is missing
const rawTime = query.time || (meetingDate && meetingTime ? `${meetingDate}T${meetingTime}` : null);
const slot = query.slot || query.Duration || '30';

if (!rawTime || !rawEmail) {
  throw new Error('Missing params. Got: ' + JSON.stringify(query));
}

const decoded = decodeURIComponent(rawEmail);
const emailMatch = decoded.match(/<([^>]+)>/);
const email = emailMatch ? emailMatch[1].trim() : decoded.trim();

const decodedTime = decodeURIComponent(rawTime);
const startDt = new Date(decodedTime);

if (isNaN(startDt.getTime())) {
  throw new Error('Invalid time: ' + decodedTime);
}

const endDt = new Date(startDt.getTime() + 30 * 60 * 1000);

return [{
  json: {
    lead_email: email,
    slot_number: slot,
    start_time: startDt.toISOString(),
    end_time: endDt.toISOString(),
    summary: 'Discovery Call',
    description: 'Meeting scheduled via AI assistant'
  }
}];

// --- Extract meeting details from the Google Calendar event creation response ---
const resp = $input.item.json;

// Prefer the attendee email echoed back by Google Calendar itself - this works
// whether this run came from a booking-link click (Code in JavaScript2) or the
// manual booking form (Prepare Manual Booking), since both paths converge here.
let leadEmail = (resp.attendees && resp.attendees[0] && resp.attendees[0].email) || null;
if (!leadEmail) {
  try {
    leadEmail = $('Code in JavaScript').item.json.lead_email;
  } catch (e) {
    leadEmail = $('Prepare Manual Booking').item.json.lead_email;
  }
}

const startIso = resp.start && resp.start.dateTime;
const entryPoints = (resp.conferenceData && resp.conferenceData.entryPoints) || [];
const meetLink = resp.hangoutLink || (entryPoints.find(e => e.entryPointType === 'video') || {}).uri || null;
const summary = resp.summary || 'Discovery Call';

if (!startIso) {
  throw new Error('Could not parse start time from Google Calendar response: ' + JSON.stringify(resp).slice(0, 500));
}

const startDt = new Date(startIso);

const dateStr = startDt.toLocaleDateString('en-IN', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'Asia/Kolkata'
});
const timeStr = startDt.toLocaleTimeString('en-IN', {
  hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Kolkata'
});

const day = startDt.getDate();
const month = startDt.toLocaleString('en-IN', { month: 'long', timeZone: 'Asia/Kolkata' }).toUpperCase();
const year = startDt.getFullYear();
const weekday = startDt.toLocaleString('en-IN', { weekday: 'long', timeZone: 'Asia/Kolkata' });

// First weekday of the month (0=Sun)
const firstDay = new Date(startDt.getFullYear(), startDt.getMonth(), 1).getDay();
// Days in month
const daysInMonth = new Date(startDt.getFullYear(), startDt.getMonth() + 1, 0).getDate();

// Build mini calendar cells
let calCells = '';
for (let i = 0; i < firstDay; i++) {
  calCells += `<td style="width:14.28%;text-align:center;padding:2px 0;font-size:9px;"></td>`;
}
for (let d = 1; d <= daysInMonth; d++) {
  const isToday = d === day;
  calCells += isToday
    ? `<td style="width:14.28%;text-align:center;padding:2px 0;">
         <span style="display:inline-block;width:18px;height:18px;line-height:18px;background:#059669;color:#ffffff;border-radius:50%;font-size:9px;font-weight:700;">${d}</span>
       </td>`
    : `<td style="width:14.28%;text-align:center;padding:2px 0;font-size:9px;color:#6b7280;">${d}</td>`;
  if ((firstDay + d) % 7 === 0 && d !== daysInMonth) {
    calCells += '</tr><tr>';
  }
}

// Meet link section
const meetSection = meetLink ? `
  <tr>
    <td style="padding:0 24px 20px;">
      <table width="100%" cellpadding="0" cellspacing="0" style="background:#F0FDF4;border:1px solid #BBF7D0;border-radius:12px;">
        <tr>
