            <p style="font-size:11px;color:#059669;font-weight:700;margin:0 0 10px;text-transform:uppercase;letter-spacing:0.06em;">&#128279; Video Link</p>
            <table width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:8px;border:1px solid #BBF7D0;">
              <tr>
                <td style="padding:12px 14px;">
                  <table cellpadding="0" cellspacing="0">
                    <tr>
                      <td style="width:36px;height:36px;background:#1D4ED8;border-radius:8px;text-align:center;vertical-align:middle;font-size:18px;">&#128249;</td>
                      <td style="padding-left:10px;">
                        <a href="${meetLink}" style="display:block;font-size:13px;font-weight:700;color:#1D4ED8;text-decoration:none;">Join Google Meet</a>
                        <span style="font-size:11px;color:#6b7280;">${meetLink}</span>
                      </td>
                    </tr>
                  </table>
                </td>
              </tr>
            </table>
          </td>
        </tr>
      </table>
    </td>
  </tr>` : `
  <tr>
    <td style="padding:0 24px 20px;">
      <table width="100%" cellpadding="0" cellspacing="0" style="background:#FFF7ED;border:1px solid #FED7AA;border-radius:12px;">
        <tr>
          <td style="padding:14px 16px;font-size:13px;color:#92400E;text-align:center;">
            &#128249; A Google Meet link will be included in your calendar invite.
          </td>
        </tr>
      </table>
    </td>
  </tr>`;

// ISO string for countdown
const isoStart = startDt.toISOString();

const confirmBody = `<!DOCTYPE html>
