    <!-- HEADER -->
    <div style="background:#059669;padding:40px 24px 32px;text-align:center;">
      <table cellpadding="0" cellspacing="0" style="margin:0 auto 16px;">
        <tr>
          <td style="width:64px;height:64px;background:rgba(255,255,255,0.2);border:2px solid rgba(255,255,255,0.6);border-radius:50%;text-align:center;vertical-align:middle;font-size:30px;line-height:64px;color:#ffffff;">
            &#10003;
          </td>
        </tr>
      </table>
      <div style="color:#ffffff;font-size:22px;font-weight:700;margin-bottom:6px;">You're confirmed!</div>
