<script>
(function() {
  // Confetti
  var cf = document.getElementById('cf');
  var colors = ['#059669','#1D4ED8','#F59E0B','#EF4444','#8B5CF6','#EC4899','#10B981'];
  for (var i = 0; i < 40; i++) {
    var el = document.createElement('div');
    var size = 6 + Math.random() * 8;
    el.style.cssText = 'position:absolute;left:' + (Math.random()*100) + '%;top:-10px;width:' + size + 'px;height:' + size + 'px;background:' + colors[Math.floor(Math.random()*colors.length)] + ';border-radius:' + (Math.random()>0.5?'50%':'2px') + ';animation:confettiFall ' + (1.5+Math.random()*2) + 's ' + (Math.random()*1.5) + 's ease-in forwards;';
    cf.appendChild(el);
  }
  setTimeout(function(){ cf.innerHTML=''; }, 5000);

  // Countdown
  var target = new Date('${isoStart}').getTime();
  var cdEl = document.getElementById('countdown');

  function tick() {
    var diff = target - Date.now();
    if (diff <= 0) {
      cdEl.innerHTML = '<span style="font-size:14px;color:#059669;font-weight:700;animation:pulse 1s infinite;">&#128250; Meeting is live now!</span>';
      return;
    }
    var d = Math.floor(diff/86400000);
    var h = Math.floor((diff%86400000)/3600000);
    var m = Math.floor((diff%3600000)/60000);
    var s = Math.floor((diff%60000)/1000);
    var units = [{v:d,l:'days'},{v:h,l:'hrs'},{v:m,l:'min'},{v:s,l:'sec'}];
    cdEl.innerHTML = units.map(function(u){
      return '<div style="min-width:48px;text-align:center;">'
        + '<div style="font-size:24px;font-weight:700;color:#111827;line-height:1;">' + String(u.v).padStart(2,'0') + '</div>'
        + '<div style="font-size:10px;color:#9ca3af;margin-top:2px;">' + u.l + '</div>'
        + '</div>';
    }).join('<div style="font-size:24px;font-weight:700;color:#d1d5db;padding-top:0;">:</div>');
  }

  tick();
  setInterval(tick, 1000);
})();
</script>
