return [{
  json: {
    lead_email: leadEmail,
    subject: `Confirmed: Your ${summary} is Scheduled!`,
    body: confirmBody,
    meet_link: meetLink,
    summary: summary,
    start_time: isoStart
  }
}];

const fireflies = $('Fireflies - List Recent Transcripts').first().json.data?.transcripts || [];
const pending = $input.all().map(i => i.json);

const matches = [];
for (const t of fireflies) {
  if (!t.meeting_link) continue;
  const found = pending.find(p => p.meet_link === t.meeting_link);
  if (found) {
    matches.push({
      json: {
        meeting_id: t.id,
        lead_email: found.lead_email,
        meet_link: t.meeting_link,
        event_id: found.event_id
      }
    });
  }
}
return matches;
